"""Write results/cost_model_selene.md: Selene refit vs proxy fit, all numbers from the metric/coef CSVs."""
import os, re, pandas as pd, numpy as np
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); R = os.path.join(ROOT, "results")
sel = pd.read_csv(os.path.join(R, "cost_model_selene_metrics.csv")); prx = pd.read_csv(os.path.join(R, "cost_model_metrics.csv"))
cs = pd.read_csv(os.path.join(R, "cost_model_selene_coefficients.csv")); cp = pd.read_csv(os.path.join(R, "cost_model_coefficients.csv"))
iA = pd.read_csv(os.path.join(R, "cost_model_selene_input_A.csv")); iB = pd.read_csv(os.path.join(R, "cost_model_selene_input_B1.csv"))
raw = pd.read_csv(os.path.join(R, "selene_depolarizing_full.csv"))
L = ["# Cost model refit on Selene depolarising data", ""]
L.append("Generated by `model/build_selene_cost_inputs.py`, `model/cost_model.py --family-a results/cost_model_selene_input_A.csv "
         "--family-b results/cost_model_selene_input_B1.csv` and `model/report_selene_cost.py`. Script outputs: "
         "`results/cost_model_selene_metrics.csv`, `results/cost_model_selene_coefficients.csv`, `results/cost_model_selene_fig.{pdf,png}`. "
         "Proxy numbers are read from `results/cost_model_metrics.csv` (unchanged).")
L += ["", "## Data", ""]
L.append("- [F] Selene rows: A %d (n = %s, pipelines %s), B1 %d (n = %s, from %d circuits). Proxy rows: A 540 (n = 4, 6, 8, pipelines P0ref, P0, P1, P2, P3), B1 35 (7 circuits)."
         % (len(iA), ", ".join(map(str, sorted(iA.n.unique()))), ", ".join(sorted(iA.pipeline.unique())), len(iB),
            ", ".join(map(str, sorted(iB.n.unique()))), iB.file.nunique()))
L.append("- [F] Features n_2q, n_1q, support_size from the Selene CSV. n_qubits and depth_2q joined from `family_A_counts.csv` / `family_B1_counts.csv` on (file, pipeline). n_2q and n_1q agree with the counts files on every row. support_size agrees with the proxy CSVs on all overlapping rows.")
r1 = raw.F_H_selene_depol / raw.F_H_selene_noiseless_sameseed; r2 = raw.F_H_selene_depol / raw.F_H_ideal_sampled_mean
m = raw.F_H_proxy_exact.notna()
L.append("- [F] Target F_H = F_H_selene_depol / F_H_selene_noiseless_sameseed. On the %d rows with a proxy row, mean (target - F_H_proxy_exact) = %+.5f, mean |.| = %.5f. "
         "Raw F_H_selene_depol: %+.5f / %.5f. Dividing by F_H_ideal_sampled_mean instead: %+.5f / %.5f. Rows with corrected F_H > 1 (y < 0): %d."
         % (m.sum(), (r1 - raw.F_H_proxy_exact)[m].mean(), (r1 - raw.F_H_proxy_exact)[m].abs().mean(),
            (raw.F_H_selene_depol - raw.F_H_proxy_exact)[m].mean(), (raw.F_H_selene_depol - raw.F_H_proxy_exact)[m].abs().mean(),
            (r2 - raw.F_H_proxy_exact)[m].mean(), (r2 - raw.F_H_proxy_exact)[m].abs().mean(), (r1 > 1).sum()))
L.append("- [O] The same-seed ratio is used because the proxy target is the exact Hellinger fidelity and the ratio removes the finite-shot bias of the raw sampled F_H to within the sampling noise. The two correction conventions are equivalent to 4e-5 in mean |.|.")

def get(df, model, split, train, test):
    r = df[(df.model == model) & (df.split == split) & (df.train == train) & (df.test == test)]
    return r.iloc[0] if len(r) else None
cases = [("lofo A->B1", "lofo", "A", "B1"), ("lofo B1->A", "lofo", "B1", "A"),
         ("cv5g, A rows", "cv5g", "A+B1 (4/5)", "A rows of fold"), ("cv5g, B1 rows", "cv5g", "A+B1 (4/5)", "B1 rows of fold"),
         ("cv5g, pooled", "cv5g", "A+B1 (4/5)", "A+B1 (1/5)"),
         ("lomo ladder", "lomo", "A minus ladder", "A ladder"), ("lomo tfim", "lomo", "A minus tfim", "A tfim"), ("lomo xxz", "lomo", "A minus xxz", "A xxz")]
L += ["", "## Selene vs proxy (R^2 of y = -ln F_H, MAE of F_H)", "",
      "| split | model | n test (proxy / Selene) | R^2 proxy | R^2 Selene | MAE(F_H) proxy | MAE(F_H) Selene |", "|---|---|---|---|---|---|---|"]
for lab, sp, tr, te in cases:
    for mo in ["physics", "ols", "ridge", "gbr"]:
        p, s = get(prx, mo, sp, tr, te), get(sel, mo, sp, tr, te)
        L.append("| %s | %s | %d / %d | %.3f | %.3f | %.4f | %.4f |" % (lab, mo, p.n_test, s.n_test, p.r2_y, s.r2_y, p.mae_F, s.mae_F))
L += ["", "## Selene metrics, all splits", "", "| model | split | train | test | n | RMSE(y) | R^2(y) | MAE(F_H) |", "|---|---|---|---|---|---|---|---|"]
for _, r in sel.iterrows():
    L.append("| %s | %s | %s | %s | %d | %.4f | %.3f | %.4f |" % (r.model, r.split, r.train, r.test, r.n_test, r.rmse_y, r.r2_y, r.mae_F))
L += ["", "## Coefficients (Selene fit, with proxy value for comparison)", "",
      "OLS SEs are homoscedastic and optimistic (rows of one circuit are not independent). GBR row = permutation importance, cv5g out-of-fold.", "",
      "| model | train | feature | Selene value | Selene SE | Selene t | proxy value |", "|---|---|---|---|---|---|---|"]
key = ["model", "train", "feature"]
mm = cs.merge(cp[key + ["value"]], on=key, how="left", suffixes=("", "_proxy"))
for _, r in mm.iterrows():
    f = lambda x, fmt: "" if pd.isna(x) else fmt % x
    L.append("| %s | %s | %s | %s | %s | %s | %s |" % (r.model, r.train, r.feature, f(r.value, "%.3e"), f(r.get("se"), "%.2e"),
             f(r.get("t"), "%.1f"), f(r.value_proxy, "%.3e")))
L += ["", "## Note", "", "- [F] The verdict paragraph that `cost_model.py` writes into its own cost_model.md hard-codes \"7 B1 circuits\" (line 457). The Selene B1 set has %d circuits. That auto-generated file was not copied into results/." % iB.file.nunique()]
open(os.path.join(R, "cost_model_selene.md"), "w").write("\n".join(L) + "\n")
print("\n".join(L[:40]))
